import zipfile, re
from pptx import Presentation

pptx_path = '/root/input.pptx'
with zipfile.ZipFile(pptx_path) as z:
    embeds = [n for n in z.namelist() if n.startswith('ppt/embeddings/')]
print('embeddings:', embeds)

prs = Presentation(pptx_path)
texts = []
for si, slide in enumerate(prs.slides, 1):
    for shape in slide.shapes:
        if getattr(shape, 'has_text_frame', False):
            t = shape.text.strip()
            if t:
                texts.append((si, t))
print('text count', len(texts))
for si, t in texts:
    if re.search(r'\b[A-Z]{3}\b', t) or re.search(r'\d', t):
        print('slide', si, 'text:', t)
